import {
    Mesh,
    PlaneGeometry,
    MeshBasicNodeMaterial,
    Object3D
} from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
    // Extract placement info with sensible defaults
    const {
        scenePosition = { x: 0, y: 0, z: 0 },
        sceneRotation = { x: 0, y: 0, z: 0 },
        sceneScale = { x: 1, y: 1, z: 1 },
        assets = {}
    } = config;

    // Load texture synchronously via context loader (cached)
    const texture = ctx.textureLoader?.(assets.imageUrl);

    // Create basic node material with the loaded texture
    const material = new MeshBasicNodeMaterial({
        map: texture,
        transparent: true,
        depthWrite: true
    });

    // Plane geometry (unit size – can be scaled later)
    const geometry = new PlaneGeometry(1, 1);

    // Mesh container
    const mesh = new Mesh(geometry, material);

    // Apply transform
    mesh.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
    mesh.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
    mesh.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

    // Attach empty handlers container
    mesh.userData.handlers = {};

    // Apply any cinematic primitives listed in config (if any)
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[primitive.name];
            if (typeof fn === 'function') {
                fn(mesh, primitive.params);
            }
        }
    }

    // Cleanup routine
    mesh.userData.cleanup = () => {
        // Dispose Three.js resources
        geometry.dispose();
        material.dispose();
        if (texture && typeof texture.dispose === 'function') {
            texture.dispose();
        }
        // Kill any GSAP timelines that might have been created
        gsap.globalTimeline.clear();
    };

    return mesh;
}
